import { test } from "node:test";
import assert from "node:assert/strict";
import { Table } from "../src/stays/table.ts";
import { ReservationRepo, type Reservation } from "../src/stays/reservations.ts";
import { arrivalsSheet, roomsOccupied } from "../src/stays/frontDesk.ts";
import { bookRoom, SoldOutError } from "../src/stays/booking.ts";

function setup() {
    const table = new Table();
    const repo = new ReservationRepo(table);
    let n = 0;
    const newId = () => `r${++n}`;
    return { table, repo, newId };
}

const stay = (over: Partial<Reservation>): Reservation => ({
    id: "r1",
    hotelId: "lisbon",
    guestId: "g-maria",
    roomType: "standard",
    checkIn: "2026-12-04",
    nights: 2,
    ...over,
});

test("a saved reservation can be read back and appears in the guest's trips", async () => {
    const { repo } = setup();
    await repo.save(stay({ id: "r1" }));
    assert.equal((await repo.get("g-maria", "r1"))?.checkIn, "2026-12-04");
    assert.deepEqual((await repo.forGuest("g-maria")).map((r) => r.id), ["r1"]);
    assert.equal(await repo.get("g-other", "r1"), null);
});

test("the arrivals sheet lists only that day's arrivals at that hotel", async () => {
    const { repo } = setup();
    await repo.save(stay({ id: "r1", guestId: "g-ana", checkIn: "2026-12-04" }));
    await repo.save(stay({ id: "r2", guestId: "g-ben", checkIn: "2026-12-05" }));
    await repo.save(stay({ id: "r3", guestId: "g-cat", checkIn: "2026-12-04", hotelId: "porto" }));
    await repo.save(stay({ id: "r4", guestId: "g-dan", checkIn: "2026-12-04", roomType: "suite" }));
    const sheet = await arrivalsSheet(repo, "lisbon", "2026-12-04");
    assert.deepEqual(sheet.map((l) => l.reservationId).sort(), ["r1", "r4"]);
});

test("a guest who books two rooms for the same night gets both on the arrivals sheet", async () => {
    const { repo } = setup();
    await repo.save(stay({ id: "r1", roomType: "deluxe" }));
    await repo.save(stay({ id: "r2", roomType: "standard" }));
    const sheet = await arrivalsSheet(repo, "lisbon", "2026-12-04");
    console.log("arrivals sheet for 2026-12-04:", sheet);
    assert.deepEqual(sheet.map((l) => [l.reservationId, l.roomType]).sort(), [["r1", "deluxe"], ["r2", "standard"]]);
    assert.equal((await repo.forGuest("g-maria")).length, 2);
});

test("occupancy counts every room of a family booking", async () => {
    const { repo } = setup();
    await repo.save(stay({ id: "r1", roomType: "standard", nights: 3 }));
    await repo.save(stay({ id: "r2", roomType: "standard", nights: 3 }));
    await repo.save(stay({ id: "r3", roomType: "suite", guestId: "g-lee", checkIn: "2026-12-05", nights: 1 }));
    assert.deepEqual(await roomsOccupied(repo, "lisbon", "2026-12-05"), { standard: 2, deluxe: 0, suite: 1 });
});

test("a stay counts as occupied every night until checkout, and not on the checkout night", async () => {
    const { repo } = setup();
    await repo.save(stay({ id: "r1", checkIn: "2026-11-28", nights: 5 }));
    assert.equal((await roomsOccupied(repo, "lisbon", "2026-11-28")).standard, 1);
    assert.equal((await roomsOccupied(repo, "lisbon", "2026-12-02")).standard, 1);
    assert.equal((await roomsOccupied(repo, "lisbon", "2026-12-03")).standard, 0);
    assert.equal((await roomsOccupied(repo, "lisbon", "2026-11-27")).standard, 0);
});

test("booking never sells more rooms of a type than the hotel has", async () => {
    const { repo, newId } = setup();
    const inventory = { standard: 10, deluxe: 2, suite: 1 };
    const request = { hotelId: "lisbon", guestId: "g-maria", roomType: "deluxe" as const, checkIn: "2026-12-04", nights: 2 };
    await bookRoom(repo, inventory, request, newId);
    await bookRoom(repo, inventory, request, newId);
    await assert.rejects(bookRoom(repo, inventory, request, newId), SoldOutError);
    assert.equal((await roomsOccupied(repo, "lisbon", "2026-12-04")).deluxe, 2);
});

test("cancelling one of a guest's two rooms keeps the other one booked", async () => {
    const { repo } = setup();
    await repo.save(stay({ id: "r1" }));
    await repo.save(stay({ id: "r2" }));
    assert.equal(await repo.cancel("g-maria", "r1"), true);
    assert.equal(await repo.cancel("g-maria", "r1"), false);
    assert.deepEqual((await arrivalsSheet(repo, "lisbon", "2026-12-04")).map((l) => l.reservationId), ["r2"]);
    assert.deepEqual((await repo.forGuest("g-maria")).map((r) => r.id), ["r2"]);
});

test("a returning guest's separate trips are all kept", async () => {
    const { repo } = setup();
    await repo.save(stay({ id: "r1", checkIn: "2026-12-04" }));
    await repo.save(stay({ id: "r2", checkIn: "2027-01-15" }));
    assert.deepEqual((await repo.arrivals("lisbon", "2026-12-01", "2027-01-31")).map((r) => r.id), ["r1", "r2"]);
});
